import pandas as pd
import numpy as np

DATASET_PATH = 'chunks_csv/moran_local_2023_energy.csv'

# Load data
energy_df = pd.read_csv(DATASET_PATH)
adj_df = pd.read_csv(ADJACENCY_PATH)

# Build neighbor dictionary
neighbors = {}
for _, row in adj_df.iterrows():
    b1, b2 = row['borough'], row['neighbor']
    if b1 not in neighbors:
        neighbors[b1] = []
    if b2 not in neighbors:
        neighbors[b2] = []
    neighbors[b1].append(b2)
    neighbors[b2].append(b1)

# Compute overall mean
overall_mean = energy_df['Energy_value'].mean()
borough_energy = dict(zip(energy_df['borough'], energy_df['Energy_value']))

# Calculate neighbor averages
neighbor_avg = {}
for borough in energy_df['borough']:
    if borough not in neighbors:
        neighbor_avg[borough] = 0
    else:
        neighbor_list = neighbors[borough]
        neighbor_energies = [borough_energy[neighbor] for neighbor in neighbor_list if neighbor in borough_energy]
        if not neighbor_energies:
            neighbor_avg[borough] = 0
        else:
            neighbor_avg[borough] = np.mean(neighbor_energies)

# Calculate observed products
observed_products = {b: e * neighbor_avg[b] for b, e in borough_energy.items()}

# Permutation test
num_permutations = 500
energy_values = energy_df['Energy_value'].values
permuted_products = {b: [] for b in energy_df['borough']}

for _ in range(num_permutations):
    shuffled_energy = np.random.permutation(energy_values)
    shuffled_borough_energy = dict(zip(energy_df['borough'], shuffled_energy))

    permuted_neighbor_avg = {}
    for b in energy_df['borough']:
        if b not in neighbors:
            permuted_neighbor_avg[b] = 0
        else:
            neighbor_list = neighbors[b]
            neighbor_energies = [shuffled_borough_energy[n] for n in neighbor_list if n in shuffled_borough_energy]
            if not neighbor_energies:
                permuted_neighbor_avg[b] = 0
            else:
                permuted_neighbor_avg[b] = np.mean(neighbor_energies)

    for b in energy_df['borough']:
        permuted_products[b].append(shuffled_borough_energy[b] * permuted_neighbor_avg[b])

# Identify significant hot/cold spots
results = []
for borough in energy_df['borough']:
    observed = observed_products[borough]
    energy = borough_energy[borough]
    avg_neighbor = neighbor_avg[borough]

    if energy > overall_mean and avg_neighbor > overall_mean:
        count_higher = sum(1 for p in permuted_products[borough] if p >= observed)
        p_value = count_higher / num_permutations
        if p_value < 0.05:
            results.append((borough, 'HH', p_value))
    elif energy < overall_mean and avg_neighbor < overall_mean:
        count_lower = sum(1 for p in permuted_products[borough] if p <= observed)
        p_value = count_lower / num_permutations
        if p_value < 0.05:
            results.append((borough, 'LL', p_value))

# Output results
print("Hot and Cold Spots:")
for borough, typ, p in results:
    print(f"{borough} ({typ}, p-value={p:.4f})")
